public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {

        // Check if the target graph is null
        if (target == null) {
            throw new IllegalArgumentException("Target graph cannot be null");
        }

        // Check if the result map is null or empty
        if (resultMap == null || resultMap.isEmpty()) {
            throw new IllegalArgumentException("Result map cannot be null or empty");
        }

        // Create a bipartite graph with the given map
        Map<String, Set<V>> vertexSets = new HashMap<>();
        Set<E> edges = new HashSet<>();

        // Loop through each entry in the map and add vertices and edges to the graph
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            V vertex = entry.getValue();
            vertexSets.computeIfAbsent(entry.getKey(), k -> new HashSet<>()).add(vertex);
            for (V otherVertex : vertexSets.get(entry.getKey())) {
                E edge = target.addEdge(vertex, otherVertex);
                edges.add(edge);
            }
        }

        // Add all the edges to the graph
        target.addAllEdges(edges);
    }
}

