public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check for valid inputs
    if (buf == null || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid input: buf must not be null and nameStart must be a valid index within the buf");
    }

    // Extract the name to abbreviate
    String name = buf.substring(nameStart);

    // Check for empty string
    if (name.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: must provide a non-empty string");
    }

    // Split the name into words
    String[] words = name.split(" ");

    // Loop over each word and abbreviate it
    for (int i = 0; i < words.length; i++) {
        // Check for valid word
        if (words[i].isEmpty()) {
            throw new IllegalArgumentException("Invalid input: must provide a list of non-empty words");
        }

        // Abbreviate the word
        words[i] = words[i].substring(0, 1);
    }

    // Concatenate the abbreviated words back into a single string
    name = String.join(" ", words);

    // Append the abbreviated name to the buffer
    buf.append(name);
}

