private static Type resolveBound(TypeVariable<?> typeVariable, List<Type> bounds) {
    if (bounds.isEmpty()) {
        return Unknown.class;
    }

    List<Type> upperBounds = bounds.stream().filter(type -> type.getUpperBounds().length == 1).collect(Collectors.toList());
    if (upperBounds.size() == 1) {
        return upperBounds.get(0);
    }

    List<Type> lowerBounds = bounds.stream().filter(type -> type.getLowerBounds().length == 1).collect(Collectors.toList());
    if (lowerBounds.size() == 1) {
        return lowerBounds.get(0);
    }

    throw new IllegalStateException("Multiple bounds for type variable " + typeVariable.getName() + " could not be resolved");
}

